WITH valid_shipments AS (SELECT * FROM shipments WHERE status NOT IN ('RETURNED', 'DELIVERED', 'LOST')), agg AS (SELECT CASE WHEN carrier IN ('DHL', 'UPS') THEN 'core' ELSE 'other' END AS carrier_group, COUNT(CASE WHEN carrier = 'Flash' THEN 1 END) AS flash_count FROM valid_shipments GROUP BY CASE WHEN carrier IN ('DHL', 'UPS') THEN 'core' ELSE 'other' END) SELECT carrier_group, flash_count FROM agg ORDER BY flash_count, carrier_group DESC;
